 "keywords": {
  "declarative": {
   "term": "Declarative",
   "def": "You describe the result you want, and the database works out how to get it. SQL is declarative."
  },
  "result-set": {
   "term": "Result set",
   "def": "The table a query returns. It has its own columns and rows, like any other table."
  },
  "alias": {
   "term": "Alias",
   "def": "A name given with AS to a column or table inside a query, like price * 1.1 AS new_price."
  },
  "distinct": {
   "term": "DISTINCT",
   "def": "Removes duplicate rows from a result, keeping one copy of each."
  },
  "predicate": {
   "term": "Predicate",
   "def": "A test that is true or false for each row, like city = 'Lisbon'. WHERE keeps the rows where it's true."
  },
  "order-by": {
   "term": "ORDER BY",
   "def": "Sorts the result, ascending unless you add DESC. Without it, the row order isn't guaranteed."
  },
  "limit": {
   "term": "LIMIT",
   "def": "Keeps only the first N rows of the result. Sort first, or you get any N rows."
  },
  "logical-order": {
   "term": "Logical query order",
   "def": "The order the clauses are evaluated: FROM, WHERE, SELECT, ORDER BY, then LIMIT. It's why an alias works in ORDER BY but not in WHERE."
  }
 },
